function badge(parent,label,state='Success'){return labelInstance(components['Badge/'+state],parent,label)}
function field(parent,label,value,state='Default',ic=null,w=342){let n=instance(components['Field/'+state],parent,w);for(const [k]of Object.entries(components['Field/'+state].componentPropertyDefinitions)){if(k.startsWith('Label#'))n.setProperties({[k]:label});if(k.startsWith('Value#'))n.setProperties({[k]:value})}let inner=n.findOne(x=>x.name==='Input surface');inner.resize(w,52);let valueText=inner.findOne(x=>x.type==='TEXT');valueText.resize(w-(ic?56:28),valueText.height);let ii=inner.findOne(x=>x.type==='INSTANCE');ii.visible=!!ic;if(ic)ii.swapComponent(icons[ic]);return n}
