function service(parent,ic,title,sub,target,w=342){let n=instance(components.ServiceRow,parent,w);n.setProperties({[keys[components.ServiceRow.id].title]:title,[keys[components.ServiceRow.id].sub]:sub});let slot=n.findOne(x=>x.name==='Service icon');slot.children[0].swapComponent(icons[ic]);if(target)links.push([n,target]);return n}
