async function organizeVariants(){
for(let c of [components.ServiceRow,components['Navigation/Active'],components['Navigation/Default'],components['Choice/Selected'],components['Choice/Default']]){let ii=c.findOne(n=>n.type==='INSTANCE');if(ii){let main=await ii.getMainComponentAsync();let key=c.addComponentProperty('Icon','INSTANCE_SWAP',main.id);ii.componentPropertyReferences={...ii.componentPropertyReferences,mainComponent:key}}}
for(let [family,axis,values]of [['Button','Style',['Primary','Secondary','Quiet','Disabled']],['Field','State',['Default','Focus','Error']],['Navigation','State',['Active','Default']],['Choice','State',['Selected','Default']],['Badge','Status',['Success','Pending']]]){
let nodes=values.map(v=>components[family+'/'+v]);let parent=nodes[0].parent;nodes.forEach((n,i)=>n.name=axis+'='+values[i]);let cs=remember(figma.combineAsVariants(nodes,parent));cs.name='AdvanCare / '+family;cs.description='Shared '+family.toLowerCase()+' family. Editable text properties and color-variable bindings.';let x=16,h=0;nodes.forEach(n=>{n.x=x;n.y=16;x+=n.width+20;h=Math.max(h,n.height)});cs.resize(x-4,h+32);
}

}

async function connect(){for(let [n,target]of links){if(!screens[target])continue;await n.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:screens[target].id,navigation:'NAVIGATE',transition:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:0.18},preserveScrollPosition:false}]}])}pg.flowStartingPoints=[{nodeId:screens.Welcome.id,name:'AdvanCare · Core journey'},{nodeId:screens.Home.id,name:'Explore care services'}]}
function scrollRegions(){for(let f of Object.values(screens)){let body=f.findOne(n=>n.name==='Scrollable content');if(!body)continue;let top=body.y;let safe=f.findOne(n=>n.name==='Primary navigation')?750:f.findOne(n=>n.name==='Fixed action · safe area')?730:820;if(f===screens.Assistant)safe=674;let port=box(f,'Content viewport / scroll vertically',390,safe-top,null);at(port,0,top);port.layoutMode='VERTICAL';port.primaryAxisSizingMode='FIXED';port.counterAxisSizingMode='FIXED';port.paddingLeft=port.paddingRight=24;port.clipsContent=true;port.overflowDirection='VERTICAL';port.appendChild(body);body.layoutSizingVertical='HUG';body.layoutSizingHorizontal='FIXED';}}
function documentation(){let top=stack(pg,'Design direction / sources / implementation notes',2248,16,32,'deep');at(top,80,40);top.cornerRadius=22;text(top,'AdvanCare / Refined care',36,'white','Semi Bold');text(top,'Familiar journeys. A calmer rhythm. Care that feels close to home.',20,'lime','Semi Bold');text(top,'16 baseline views + supporting prototype states   /   390 × 844   /   Inter   /   Solar Linear   /   4 & 8 pt spacing',14,'white','Medium');let doc=stack(pg,'Design rationale and accessibility handoff',1300,20,32,'white');at(doc,2510,1700);doc.cornerRadius=20;text(doc,'Built for confidence, not decoration.',28,'ink','Semi Bold');let notes=[['Brand','AdvanCare wordmark, teal / green identity, heart-and-leaf motif, community landscape, Philippine peso pricing, and familiar services. The editable vector emblem is a reconstruction from the supplied raster; replace with the official vector when available.'],['Reference audit','The supplied “15-screen” image contains 16 distinct views. All 16 are represented in the first 16 frames, in reading order. Supporting states follow them. Original file pages are preserved.'],['Typography & layout','Inter 16/24 body, 24/34 and 28/34 headings, 36/42 welcome. 24 pt page gutters. 52 pt primary actions. Safe areas: 48 pt status and 84 pt navigation. Auto layout for all related text, controls, rows, and cards.'],['Accessibility','Primary and secondary text pairs exceed 4.5:1. Controls use labels and 44–52 pt touch areas. Selection uses check marks and borders. Status uses visible words. Treat this as a design handoff: verify screen-reader semantics, native text scaling, and reduced motion during implementation.'],['Interaction','180 ms dissolve between prototype views. Native implementation: use an immediate pressed response, retain field values on error, announce validation messages, move focus after navigation, and respect reduced motion. Chart values must also be available as records.'],['Report integrity','The baseline shows a 20–26 Apr period while one record is Apr 18; preserve the sample record but treat it as a sample-data discrepancy to resolve with real data. The chart uses editable illustrative values; dashboard totals and shares retain baseline values.'],['UIZZE · uizze.com','Screen and journey references: coherent mobile rhythm and purposeful hierarchy. No third-party screen was copied.'],['Taste Skill · tasteskill.dev','Audit first, preserve the product, establish typography / spacing / color rules, and avoid template decoration.'],['Impeccable · impeccable.style','Clear action labels, deliberate hierarchy, minimal nesting, and a restrained product-specific palette.'],['Details · details.so/inspo','Refine individual navigation, buttons, rows, and transitions. Production details inform the system rather than a wholesale copied layout.'],['Design Spells · designspells.com','Subtle state transitions and continuity. Avoid novelty effects in care tasks; motion is a supporting cue.'],['Solar · solar-icons.vercel.app','Solar Linear icons by 480 Design, CC BY 4.0. Source: github.com/iconify/icon-sets / solar. Standard 24 pt icons with consistent 1.5 pt strokes.'],['Prototype boundaries','Frames and components are editable. Account authentication, actual file upload / camera, live exports, service submission, and changing input values require an app implementation. Supporting frames show intended destinations; this is not a working healthcare service.']];for(let [title,body]of notes){let s=stack(doc,title,1236,4);text(s,title,18,'ink','Semi Bold');text(s,body,16,'muted','Regular',1236)}return doc}
function inspect(){return {file:figma.root.name,pages:figma.root.children.map(p=>({id:p.id,name:p.name})),currentPage:{name:figma.currentPage.name,topLevelNodes:figma.currentPage.children.length},rootNodes:figma.currentPage.children.map(n=>({id:n.id,name:n.name,type:n.type})),screenParents:figma.currentPage.findAll(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name)).map(n=>({id:n.id,name:n.name,parent:n.parent.id,parentType:n.parent.type,parentName:n.parent.name})),localComponents:figma.currentPage.findAllWithCriteria({types:['COMPONENT','COMPONENT_SET']}).length}}
function contrast(a,b){let lum=h=>{let c=rgb(h);return [c.r,c.g,c.b].map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0)};let x=lum(a),y=lum(b);return +((Math.max(x,y)+.05)/(Math.min(x,y)+.05)).toFixed(2)}
async function validate(){let p=figma.root.children.find(p=>p.name===PAGE);if(!p)return {error:'Redesign page has not been created.'};await figma.setCurrentPageAsync(p);let frames=p.children.filter(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name));let over=[];for(let f of frames){let body=f.findOne(n=>n.name==='Scrollable content');let safe=f.findOne(n=>n.name==='Primary navigation')?750:f.findOne(n=>n.name==='Fixed action · safe area')?730:820;if(body&&body.y+body.height>safe)over.push({screen:f.name,bottom:Math.round(body.y+body.height),safe})}return {pageId:p.id,coreViews:frames.slice(0,16).map(n=>({id:n.id,name:n.name})),supportingViews:frames.length-16,components:p.findAllWithCriteria({types:['COMPONENT']}).length,instances:p.findAllWithCriteria({types:['INSTANCE']}).length,textLayers:p.findAllWithCriteria({types:['TEXT']}).length,overflow:over,textContrast:{inkOnPaper:contrast(C.ink,C.paper),mutedOnWhite:contrast(C.muted,C.white),whiteOnTeal:contrast(C.white,C.teal),tealOnMint:contrast(C.teal,C.mint)},prototypeLinks:links.length,createdNodeIds:created}}
async function recoverExisting(p){
  pg=p;await figma.setCurrentPageAsync(p);
  for(let style of ['Regular','Medium','Semi Bold'])await figma.loadFontAsync({family:'Inter',style});
  let vars=await figma.variables.getLocalVariablesAsync();for(let v of vars){if(v.name.startsWith('color/'))tokens[v.name.slice(6)]=v;if(v.name.startsWith('spacing/'))tokens['space'+v.name.slice(8)]=v}
  for(let s of await figma.getLocalTextStylesAsync()){if(s.name.startsWith('AdvanCare/'))styles[s.name.slice(10)]=s}
  let fs=p.findAll(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name));
  let before=fs.map(n=>({id:n.id,name:n.name,parentId:n.parent.id,parentName:n.parent.name}));
  for(let f of fs){p.appendChild(f);let i=parseInt(f.name)-1;at(f,80+(i%5)*466,300+Math.floor(i/5)*968);screens[f.name.split(' / ')[1]]=f}
  const targets={'Get started':'Plans','I already have an account':'Sign in','Sign in':'Home','Create an account':'Help','Forgot password?':'Help','Request a service':'Services','Consult a doctor':'Tele-consultation','Book transport':'Transport','Your family, covered.':'Plans','Explore AdvanCare plans':'Plans','Ask your care assistant':'Assistant','Family':'Family profile','Client info':'Profile','Edit profile':'Edit profile','Tele-consultation':'Tele-consultation','Medical prescription':'Prescription','Non-emergency transport':'Transport','Home-based caregiver':'Home caregiver','CVMC institutional caregiver':'CVMC caregiver','Change doctor':'Choose doctor','Book consultation':'Request received','Review request':'Prescription review','Submit request':'Request received','Request caregiver':'Request received','Edit visit details':'Edit visit','Service records':'Service records','Service trends':'Service trends','Dashboard':'Dashboard','Export':'Export report','View all service records':'Service records','Check client information':'Profile','Book a service':'Services','View reports':'Reports','View report':'Service trends','Client & family profile':'Profile','Subscription plans':'Plans','Care assistant':'Assistant','Back to home':'Home','View service records':'Service records','Back to client information':'Profile','Save changes':'Profile','Save visit details':'Home caregiver','Choose Dr. Reyes':'Tele-consultation','Take a photo or upload a file':'Attachment options','Choose Basic':'Request received','Choose Family':'Request received','Choose Premium':'Request received'};
  const backs={'Welcome':'Home','Sign in':'Welcome','Home':'Welcome','Plans':'Home','Profile':'Home','Services':'Home','Tele-consultation':'Services','Prescription':'Services','Transport':'Services','Home caregiver':'Services','CVMC caregiver':'Services','Reports':'Home','Service records':'Reports','Service trends':'Reports','Dashboard':'Reports','Assistant':'Home','Prescription review':'Prescription','Family profile':'Profile','More':'Home','Request received':'Home','Help':'Sign in','Edit profile':'Profile','Edit visit':'Home caregiver','Choose doctor':'Tele-consultation','Attachment options':'Prescription','Export report':'Service records'};
  let wired=[],errors=[];
  async function wire(node,target){if(!screens[target])return;let top=node;while(top.parent&&top.parent.type!=='PAGE')top=top.parent;if(top.id===screens[target].id){await node.setReactionsAsync([]);return}try{await node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:screens[target].id,navigation:'NAVIGATE',transition:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:.18},preserveScrollPosition:false}]}]);wired.push({source:node.id,target:target})}catch(e){errors.push({source:node.id,target:target,error:String(e)})}}
  for(let [name,f]of Object.entries(screens)){
    let nav=f.findOne(n=>n.name==='Primary navigation');if(nav)for(let item of nav.children){let t=item.findOne(n=>n.type==='TEXT');if(t)await wire(item,t.characters)}
    for(let back of f.findAll(n=>n.name==='Control / alt-arrow-left'))await wire(back,backs[name]||'Home');
    for(let t of f.findAllWithCriteria({types:['TEXT']})){let target=targets[t.characters];if(!target||target===name)continue;let node=t,cur=t.parent;while(cur&&cur!==f){if(cur.type==='INSTANCE'){node=cur;break}if(cur.name==='Your family, covered.'||cur.name==='Membership'||cur.name==='Upload prescription control')node=cur;cur=cur.parent}await wire(node,target)}
  }
  p.flowStartingPoints=[{nodeId:screens.Welcome.id,name:'AdvanCare · Core journey'},{nodeId:screens.Home.id,name:'Explore care services'}];
  if(!p.children.some(n=>n.name==='Design direction / sources / implementation notes'))documentation();
  for(let [n,id]of pendingStyles)await n.setTextStyleIdAsync(id);
  figma.viewport.scrollAndZoomIntoView([screens.Home]);
  let report=await validate();report.parentsBeforeRepair=before;report.prototypeWires=wired.length;report.prototypeErrors=errors;report.rootScreens=fs.map(f=>({id:f.id,name:f.name,parent:f.parent.id}));
  figma.ui.postMessage({report,screens:Object.keys(screens),done:true});return report;
}

async function build(){if(busy)return;busy=true;let old=figma.root.children.find(p=>p.name===PAGE);if(old&&old.id==='2:2647'){await recoverExisting(old);busy=false;return}if(old){pg=old;figma.ui.postMessage({report:'Redesign page already exists. Use Validate or focus a view; it will not be overwritten.',screens:old.children.filter(n=>/^\d\d \/ /.test(n.name)).map(n=>n.name.split(' / ')[1]),done:true});busy=false;return}let before=inspect();try{const fonts=await figma.listAvailableFontsAsync();for(let style of ['Regular','Medium','Semi Bold']){if(!fonts.some(f=>f.fontName.family==='Inter'&&f.fontName.style===style))throw Error('Inter '+style+' is not available');await figma.loadFontAsync({family:'Inter',style})}pg=figma.createPage();pg.name=PAGE;await figma.setCurrentPageAsync(pg);pg.backgrounds=[{type:'SOLID',color:rgb('#E8EEE8')}];await foundations();await library();await compose();await supporting();for(let [n,id]of pendingStyles)await n.setTextStyleIdAsync(id);pendingStyles=[];scrollRegions();await organizeVariants();await connect();documentation();for(let [n,id]of pendingStyles)await n.setTextStyleIdAsync(id);let report=await validate();report.originalFile=before;figma.viewport.scrollAndZoomIntoView([screens.Home]);figma.ui.postMessage({report,screens:Object.keys(screens),done:true})}catch(e){figma.ui.postMessage({report:{error:String(e),stack:e.stack,pageId:pg&&pg.id,createdNodeIds:created},done:true})}busy=false}
figma.showUI(__html__,{width:460,height:700,themeColors:true});
figma.ui.postMessage({report:inspect()});
figma.ui.onmessage=async m=>{try{if(m.type==='build')await build();if(m.type==='validate')figma.ui.postMessage({report:await validate(),done:true});if(m.type==='focus'){let p=figma.root.children.find(p=>p.name===PAGE);if(!p)return;await figma.setCurrentPageAsync(p);let ns=m.name==='overview'?p.children.filter(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name)).slice(0,16):p.children.filter(n=>n.name.endsWith(' / '+m.name));figma.currentPage.selection=ns;figma.viewport.scrollAndZoomIntoView(ns);figma.ui.postMessage({report:{focused:m.name,nodeIds:ns.map(n=>n.id)},done:true})}}catch(e){figma.ui.postMessage({report:String(e),done:true})}};

const ONBOARD_NAMES=['Onboarding / 01 · Connected care','Onboarding / 02 · Care your way','Onboarding / 03 · Clearer picture'];
let logoMain,logoMark,onboards=[],finishErrors=[];
async function hydrate(){
 pg=figma.root.children.find(p=>p.id==='2:2647');if(!pg)throw Error('Expected redesign page 2:2647 is missing. No other page will be changed.');
 await figma.setCurrentPageAsync(pg);for(let s of ['Regular','Medium','Semi Bold'])await figma.loadFontAsync({family:'Inter',style:s});
 for(let v of await figma.variables.getLocalVariablesAsync()){if(v.name.startsWith('color/'))tokens[v.name.slice(6)]=v;if(v.name.startsWith('spacing/'))tokens['space'+v.name.slice(8)]=v}
 for(let s of await figma.getLocalTextStylesAsync()){if(s.name.startsWith('AdvanCare/'))styles[s.name.slice('AdvanCare/'.length)]=s}
 for(let c of pg.findAllWithCriteria({types:['COMPONENT']})){if(c.name.startsWith('Icon/'))icons[c.name.slice(5)]=c;if(c.name==='StatusBar')components.StatusBar=c}
 for(let f of pg.children.filter(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name)))screens[f.name.split(' / ')[1]]=f;
}
function rawLogo(parent,w=144,emblem=false){
 let f=box(parent,emblem?'Official AdvanCare emblem':'Official AdvanCare logo',emblem?40:144,emblem?40:148,null,0);f.clipsContent=true;
 let img=remember(figma.createRectangle());f.appendChild(img);img.name='Original supplied PNG · transparency preserved';img.resize(240,240);img.fills=[{type:'IMAGE',imageHash:LOGO_HASH,scaleMode:'FIT'}];at(img,-50,-38);
 if(emblem){img.resize(68,68);at(img,-14,-10)}
 if(w!==f.width)f.rescale(w/f.width);return f;
}
