function OBbutton(parent,label,w=342,secondary=false){let r=row(parent,'Action / '+label,w,10,14,secondary?'white':'teal');fixed(r,52);r.cornerRadius=12;r.primaryAxisAlignItems=r.counterAxisAlignItems='CENTER';if(secondary)border(r,'control');text(r,label,16,secondary?'teal':'white','Semi Bold');return r}
function sysIndicators(){let c=components.StatusBar;if(!c)return;let old=c.findOne(n=>n.name==='System indicators');if(old){let x=old.x,y=old.y,w=old.width,h=old.height;old.remove();let svg=remember(figma.createNodeFromSvg('<svg width="70" height="18" viewBox="0 0 70 18" xmlns="http://www.w3.org/2000/svg"><g fill="#173E37"><rect x="0" y="11" width="3" height="5" rx="1"/><rect x="5" y="8" width="3" height="8" rx="1"/><rect x="10" y="5" width="3" height="11" rx="1"/><rect x="15" y="2" width="3" height="14" rx="1"/></g><g stroke="#173E37" fill="none" stroke-width="1.8" stroke-linecap="round"><path d="M25 6Q33 0 41 6M28 10Q33 6 38 10M31 13Q33 11 35 13"/></g><circle cx="33" cy="16" r="1.3" fill="#173E37"/><rect x="48" y="4" width="18" height="10" rx="2.5" fill="none" stroke="#173E37"/><rect x="50" y="6" width="14" height="6" rx="1" fill="#173E37"/><rect x="67" y="7" width="2" height="4" rx="1" fill="#173E37"/></svg>'));c.appendChild(svg);svg.name='System indicators';svg.resize(70,18)}}
async function refreshVisuals(){
 await hydrate();
 let img=figma.createImage(new Uint8Array(LOGO_BYTES));LOGO_HASH=img.hash;
 logoMain=pg.findOne(n=>n.type==='COMPONENT'&&n.name==='Brand / Official AdvanCare logo');logoMark=pg.findOne(n=>n.type==='COMPONENT'&&n.name==='Brand / Official AdvanCare emblem');
 let lib=pg.children.find(n=>n.name==='Component library / native editable masters');
 if(!logoMain){let raw=rawLogo(lib);logoMain=asComponent(raw,'Brand / Official AdvanCare logo','Original supplied AdvanCare_Logo.png. Transparency preserved. Outer margin cropped with an editable frame.');let raw2=rawLogo(lib,40,true);logoMark=asComponent(raw2,'Brand / Official AdvanCare emblem','Emblem from the same original asset, cropped in an editable frame for compact headers.');}
 for(let c of [logoMain,logoMark]){c.fills=[];c.description='Official updated AdvanCare_Logo.png. Original image and transparency preserved.';for(let n of c.findAll(n=>n.type==='RECTANGLE')){n.fills=[{type:'IMAGE',imageHash:LOGO_HASH,scaleMode:'FIT'}];n.name='Original supplied PNG · transparency preserved';if(c===logoMark)n.y=-11}}logoMark.resize(40,35);
 let replacements=[];
 for(let name of ['Welcome','Sign in','Home']){let f=screens[name];if(!f)continue;for(let old of f.findAll(n=>n.name==='AdvanCare brand')){let p=old.parent;let pos=p.children.indexOf(old);let replacement=officialLockup(p,old.width);p.insertChild(pos,replacement);old.remove();replacements.push(replacement.id)}}
 sysIndicators();
 let existing=ONBOARD_NAMES.map(name=>pg.children.find(n=>n.name===name));
 if(existing.every(Boolean)){onboards=existing}else{
 for(let [i,name]of ONBOARD_NAMES.entries()){
 let f=box(pg,name,390,844,'white',28);f.clipsContent=true;at(f,80+i*466,-1120);onboards.push(f);status(f);homeIndicator(f);
 let top=row(f,'Onboarding navigation',342,0);fixed(top,52);top.counterAxisAlignItems='CENTER';top.primaryAxisAlignItems='SPACE_BETWEEN';at(top,24,58);officialLockup(top,246);let skip=row(top,'Skip onboarding',64,0);fixed(skip,48);skip.primaryAxisAlignItems=skip.counterAxisAlignItems='CENTER';text(skip,'Skip',14,'teal','Semi Bold');
 let art=box(f,'Slide artwork',342,268,'mint',24);at(art,24,142);art.clipsContent=true;
 if(i===0){let seal=instance(logoMain,art);at(seal,99,24);let caption=row(art,'Brand promise',294,8);caption.primaryAxisAlignItems='CENTER';at(caption,24,218);text(caption,'CARE TODAY. STRONGER TOMORROW.',11,'teal','Medium');}
 if(i===1){let card=stack(art,'Doctor appointment preview',286,12,18,'white');at(card,28,26);card.cornerRadius=18;let person=row(card,'Care professional',250,12);let av=box(person,'Doctor avatar',48,48,'mint',24);at(icon(av,'stethoscope','teal',28),10,10);let info=stack(person,'Doctor details',184,0);text(info,'Dr. Santos Reyes',16,'ink','Semi Bold');text(info,'General practitioner',13,'muted');let times=row(card,'Appointment times',250,8);for(let [j,label]of ['9:00','10:00','11:00'].entries()){let tm=row(times,'Time / '+label,78,0,9,j===1?'teal':'paper');tm.cornerRadius=9;tm.primaryAxisAlignItems='CENTER';text(tm,label,14,j===1?'white':'muted','Semi Bold')}let services=row(art,'Care options',294,12);at(services,24,197);for(let [ic,label]of [['stethoscope','Consult'],['bus','Transport'],['user-heart','Caregiver']]){let q=row(services,label,90,6);q.counterAxisAlignItems='CENTER';icon(q,ic,'teal',20);text(q,label,11,'ink','Medium')}}
 if(i===2){let card=stack(art,'Care summary preview',286,12,18,'white');at(card,28,24);card.cornerRadius=18;let h=row(card,'Report heading',250,0);h.primaryAxisAlignItems='SPACE_BETWEEN';text(h,'Your care, together',16,'ink','Semi Bold');icon(h,'chart-square','teal',22);let chart=row(card,'Activity preview',250,10);fixed(chart,88);chart.counterAxisAlignItems='MAX';for(let [j,v]of [35,55,44,70,58,78,64].entries()){let b=box(chart,'Activity '+(j+1),26,v,j===5?'teal':'#9EBDAA',5)}let q=row(art,'Assistant preview',294,10,12,'deep');q.cornerRadius=14;at(q,24,204);icon(q,'chat-round-dots','lime');text(q,'A little help, whenever you need it.',12,'white','Medium')}
 let copy=stack(f,'Onboarding story',342,14);at(copy,24,442);
 let title=['Care starts\nwith connection.','Expert care.\nA little closer.','More clarity.\nLess to keep track of.'][i];text(copy,title,32,'ink','Semi Bold',342);
 text(copy,['Support for you and the people you love, connected through AdvanCare.','Consult a doctor, arrange transport, or request a caregiver — all in one place.','Keep care records together, explore reports, and find help with your care assistant.'][i],16,'muted','Regular',342);
 let paging=row(f,'Page indicators',342,8);fixed(paging,24);paging.primaryAxisAlignItems=paging.counterAxisAlignItems='CENTER';at(paging,24,654);for(let j=0;j<3;j++){let hit=row(paging,'Go to onboarding '+(j+1),40,0);fixed(hit,44);hit.primaryAxisAlignItems=hit.counterAxisAlignItems='CENTER';box(hit,'Indicator '+(j+1),i===j?24:7,7,i===j?'teal':'line',4)}
 let next=OBbutton(f,i===2?'Continue to sign in':'Next');at(next,24,706);let signin=row(f,'Sign in shortcut',342,4);fixed(signin,44);signin.primaryAxisAlignItems=signin.counterAxisAlignItems='CENTER';at(signin,24,774);text(signin,'Already have an account?',13,'muted');text(signin,'Sign in',13,'teal','Semi Bold');
 if(i>0){let back=iconButton(f,'alt-arrow-left');at(back,14,654);back.name='Previous onboarding screen'}
 }
 }
 for(let [n,id]of pendingStyles)await n.setTextStyleIdAsync(id);pendingStyles=[];
 let rationale=pg.children.find(n=>n.name==='Design rationale and accessibility handoff');if(rationale){for(let t of rationale.findAllWithCriteria({types:['TEXT']})){if(t.characters.includes('editable vector emblem is a reconstruction')||t.characters.includes('AdvanCare_Logo.jpg'))t.characters='AdvanCare identity uses the updated supplied AdvanCare_Logo.png. The complete logo and compact emblem are reusable components; the source image and transparency are preserved.'}}
 figma.viewport.scrollAndZoomIntoView(onboards);
 figma.ui.postMessage({report:{stage:'Logo and three onboarding frames created. Finish prototype connections next.',pageId:pg.id,onboarding:onboards.map(n=>({id:n.id,name:n.name})),officialLogoComponent:logoMain.id,officialEmblemComponent:logoMark.id,replacements,createdNodeIds:created},screens:[...ONBOARD_NAMES,...Object.keys(screens)],done:true});
}
async function finishAll(){
 await hydrate();let coreAudit=await recoverExisting(pg);finishErrors=coreAudit.prototypeErrors||[];onboards=ONBOARD_NAMES.map(name=>pg.children.find(n=>n.name===name));if(onboards.some(n=>!n))throw Error('Create the onboarding frames first.');
 const connect=async(n,d,slide=false,back=false,drag=false)=>{try{let t=slide?{type:'PUSH',direction:back?'RIGHT':'LEFT',matchLayers:false,easing:{type:'EASE_OUT'},duration:.32}:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:.18};await n.setReactionsAsync([{trigger:{type:drag?'ON_DRAG':'ON_CLICK'},actions:[{type:'NODE',destinationId:d.id,navigation:'NAVIGATE',transition:t,preserveScrollPosition:false}]}]);return true}catch(e){finishErrors.push({id:n.id,target:d.id,error:String(e)});return false}};
 for(let [i,f]of onboards.entries()){await connect(f.findOne(n=>n.name==='Skip onboarding'),screens['Sign in']);await connect(f.findOne(n=>n.name==='Sign in shortcut'),screens['Sign in']);await connect(f.findOne(n=>n.name.startsWith('Action / ')),i===2?screens['Sign in']:onboards[i+1],true);if(i>0)await connect(f.findOne(n=>n.name==='Previous onboarding screen'),onboards[i-1],true,true);for(let j=0;j<3;j++){let n=f.findOne(n=>n.name==='Go to onboarding '+(j+1));if(i!==j)await connect(n,onboards[j],true,j<i)}if(i<2)await connect(f.findOne(n=>n.name==='Slide artwork'),onboards[i+1],true,false,true)}
 let start=screens.Welcome.findOne(n=>n.type==='INSTANCE'&&n.findOne(t=>t.type==='TEXT'&&t.characters==='Get started'));if(start)await connect(start,onboards[0],true);
 pg.flowStartingPoints=[{nodeId:onboards[0].id,name:'AdvanCare · Animated onboarding'},{nodeId:screens.Home.id,name:'AdvanCare · Explore care'}];
 let coreErrors=[];for(let [name,f]of Object.entries(screens)){for(let n of f.findAll(n=>'reactions' in n&&n.reactions.length)){for(let r of n.reactions){for(let a of r.actions||[]){if(a.type==='NODE'&&a.destinationId){let dest=await figma.getNodeByIdAsync(a.destinationId);if(!dest||dest.parent.id!==pg.id)coreErrors.push({source:n.id,destination:a.destinationId})}}}}}
 let audit=await finalAudit();audit.prototypeErrors=finishErrors;audit.invalidDestinations=coreErrors;figma.ui.postMessage({report:audit,screens:[...ONBOARD_NAMES,...Object.keys(screens)],done:true});return audit;
}
async function finalAudit(){let fs=pg.children.filter(n=>n.type==='FRAME'&&(/^\d\d \/ /.test(n.name)||ONBOARD_NAMES.includes(n.name)));return {pageId:pg.id,coreViews:16,supportingViews:10,onboardingViews:3,componentMasters:pg.findAllWithCriteria({types:['COMPONENT']}).length,componentFamilies:pg.findAllWithCriteria({types:['COMPONENT_SET']}).length,componentInstances:pg.findAllWithCriteria({types:['INSTANCE']}).length,editableTextLayers:pg.findAllWithCriteria({types:['TEXT']}).length,prototypeConnections:pg.findAll(n=>'reactions' in n&&n.reactions.length>0).length,originalPagePreserved:'No mutations to original page 0:1; baseline inventory verified it empty.',onboardingMotion:'320 ms PUSH / LEFT / EASE_OUT. Back uses RIGHT. Artwork supports drag forward.',textContrast:{inkOnPaper:contrast(C.ink,C.paper),mutedOnWhite:contrast(C.muted,C.white),whiteOnTeal:contrast(C.white,C.teal)},frames:fs.map(n=>({id:n.id,name:n.name,width:n.width,height:n.height})),createdNodeIds:created}}
async function presentFinished(audit){
 if(audit.prototypeErrors.length||audit.invalidDestinations.length)return;
 let proof=pg.children.find(n=>n.name==='Verification / Refined care & onboarding');if(!proof){proof=stack(pg,'Verification / Refined care & onboarding',1300,16,32,'white');at(proof,2510,5000);proof.cornerRadius=20;text(proof,'AdvanCare / verification',28,'ink','Semi Bold');text(proof,'29 editable phone frames · 16 core views + 10 supporting views + 3 onboarding screens',18,'ink','Semi Bold',1236);text(proof,audit.componentMasters+' component masters · '+audit.componentFamilies+' variant families · '+audit.componentInstances+' instances · '+audit.prototypeConnections+' prototype connections',16,'muted','Regular',1236);text(proof,'Updated transparent PNG logo is applied through shared components. Onboarding: Next, Back, Skip, Sign in, clickable page indicators, and drag forward. Sliding transition: PUSH, 320 ms, ease out. Zero invalid prototype destinations.',16,'muted','Regular',1236);text(proof,'Text contrast: primary 11.13:1; secondary 5.61:1; white on teal 6.43:1. Original page remains empty and unchanged. Native authentication, file upload, export generation, and care submission are outside the Figma prototype.',16,'muted','Regular',1236);}
 let doc=pg.children.find(n=>n.name==='Design rationale and accessibility handoff');if(doc)for(let t of doc.findAllWithCriteria({types:['TEXT']}))if(t.characters.includes('editable vector emblem is a reconstruction'))t.characters='AdvanCare identity uses the updated supplied AdvanCare_Logo.png. The full logo and compact emblem are reusable components, with the original source image and transparency preserved.';
 for(let [n,id]of pendingStyles)await n.setTextStyleIdAsync(id);pendingStyles=[];
 figma.currentPage.selection=[];figma.viewport.scrollAndZoomIntoView(onboards);
 figma.closePlugin('AdvanCare ready: 29 editable screens, '+audit.componentMasters+' components, '+audit.prototypeConnections+' connections. Sliding onboarding verified. Original page preserved.');
}
figma.ui.onmessage=async m=>{try{if(m.type==='build')await refreshVisuals();if(m.type==='finish')await finishAll();if(m.type==='validate'){await hydrate();figma.ui.postMessage({report:await finalAudit(),done:true})}if(m.type==='focus'){await hydrate();let nodes=m.name==='overview'?pg.children.filter(n=>n.type==='FRAME'&&/^\d\d \/ /.test(n.name)).slice(0,16):pg.children.filter(n=>n.name===m.name||n.name.endsWith(' / '+m.name));figma.currentPage.selection=nodes;figma.viewport.scrollAndZoomIntoView(nodes)}}catch(e){figma.ui.postMessage({report:{error:String(e),stack:e.stack},done:true})}};

refreshVisuals().then(()=>finishAll()).then(presentFinished).catch(e=>figma.ui.postMessage({report:{error:String(e),stack:e.stack},done:true}));
